-- Set programs that you use
local terminal = "kitty"
local fileManager = "thunar"
local menu = "rofi -show combi -modes 'combi,drun,hom:" .. os.getenv("HOME") .. "/.config/rofi/scripts/home.sh' -combi-modes 'hom,drun' -combi-hide-mode-prefix -display-combi 'Home' -pid /tmp/rofi-home.pid -replace"

-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function()
	--   hl.exec_cmd(terminal)
	--   hl.exec_cmd("nm-applet")

	-- Sync env vars ke DBus dan systemd user session
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE DISPLAY")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE")
	-- Polkit authentication agent untuk Hyprland (wajib agar file manager bisa mount partisi)
	hl.exec_cmd("/usr/libexec/hyprpolkitagent")
	-- Notification daemon
	hl.exec_cmd("swaync")
	-- Clear rfkill soft-block on Wi-Fi/Bluetooth adapters (e.g. MT7921) so
	-- bluetoothd catches the adapter and bluetui doesn't exit immediately.
	hl.exec_cmd("~/.config/scripts/rfkill-unblock.sh")
	-- Volume/brightness OSD (center-bottom bar, separate from notification list)
	hl.exec_cmd("~/.config/scripts/wob-daemon.sh")

	hl.exec_cmd("waybar")
	hl.exec_cmd("awww-daemon")
	hl.exec_cmd("hyprctl setcursor breeze_cursors 24")
end)

