-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

-- Floating helper windows: bluetui (bluetooth TUI) and impala-nm (network TUI)
-- launched from the waybar modules. windowrulev2 was removed in 0.56; the
-- Lua equivalent is hl.window_rule().
hl.window_rule({
	name = "float-bluetui",
	match = { class = "^kitty-bluetui$" },
	float = true,
	size = { 800, 500 },
	center = true,
})

hl.window_rule({
	name = "float-impala",
	match = { class = "^kitty-impala$" },
	float = true,
	size = { 800, 500 },
	center = true,
})

-- Flameshot on Wayland is a plain xdg_toplevel, not a layer-shell overlay, so
-- Hyprland would tile it and reflow every other window (flameshot#4948). Force
-- float + fullscreen so it covers the screen like a capture overlay.
-- Matched on title too: the Configuration dialog shares the "flameshot" class
-- and must stay a normal window.
hl.window_rule({
	name = "flameshot-overlay",
	match = { class = "^flameshot$", title = "^flameshot$" },
	float = true,
	fullscreen = true,
	no_anim = true,
})

